test("pins", "check: a poisoned folder refuses an indexed absolute passage before any open", () => {
  const db = freshDb();
  const root = realpathSync(mkdtempSync(join(tmpdir(), "chamber-check-poison-idx-")));
  const POISON = '--exclude matched nothing: "no-such" — nothing in this folder was checked';
  try {
    const note = join(root, "n.md");
    writeFileSync(note, "The audit store is SQLite.\n");
    ingestDirectory(db, root);
    const folders = [{ root, exclude: ["no-such"] }];
    const claim = { text: "The audit store is SQLite.", sources: [`${note}#p0`] };
    // The index holds this passage: resolveSource takes the indexed branch.
    const first = checkClaims(db, [claim], { folders })[0]!;
    assert(first.status === "NOT_FOUND", `indexed #p0 under a poisoned folder: ${JSON.stringify(first)}`);
    assert(first.problems.some((p) => p === POISON), JSON.stringify(first.problems));
    // Not opened: with a fifo in the note's place any open hangs or reports "regular file".
    rmSync(note);
    const fifo = spawnSync("mkfifo", [note]);
    assert(fifo.status === 0, `setup: mkfifo failed: ${fifo.stderr}`);
    const t = Date.now();
    const piped = checkClaims(db, [claim], { folders })[0]!;
    assert(Date.now() - t < 5000, "the call must return, not hang on the fifo");
    assert(piped.status === "NOT_FOUND" && piped.problems.some((p) => p === POISON), JSON.stringify(piped));
    assert(!piped.problems.some((p) => p.includes("regular file")), `the file was opened: ${JSON.stringify(piped.problems)}`);
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

test("pins", "check: the poison cache is keyed by the exclude list, not the root", () => {
  const db = freshDb();
  const root = realpathSync(mkdtempSync(join(tmpdir(), "chamber-check-poison-key-")));
  const POISON = '--exclude matched nothing: "no-such" — nothing in this folder was checked';
  try {
    mkdirSync(join(root, "skip"));
    writeFileSync(join(root, "skip", "x.md"), "Skipped.\n");
    writeFileSync(join(root, "n.md"), "The audit store is SQLite.\n");
    const claim = { text: "The audit store is SQLite.", sources: [join(root, "n.md")] };
    const poisoned = [{ root, exclude: ["no-such"] }];
    for (const round of [1, 2]) {
      const r = checkClaims(db, [claim], { folders: poisoned })[0]!;
      assert(r.status === "NOT_FOUND" && r.problems.some((p) => p === POISON), `round ${round}: ${JSON.stringify(r)}`);
    }
    // Same root, a list that matches something: a root-only key would stay poisoned.
    const real = checkClaims(db, [claim], { folders: [{ root, exclude: ["skip"] }] })[0]!;
    assert(real.status === "SUPPORTED", `a matching exclude list must give a real verdict: ${JSON.stringify(real)}`);
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

test("pins", "check: a link to a folder in the same root does not bypass a multi-segment exclude", () => {
  const db = freshDb();
  const root = realpathSync(mkdtempSync(join(tmpdir(), "chamber-check-zlink-")));
  const WHY = "excluded by --exclude work/clients";
  try {
    mkdirSync(join(root, "work", "clients"), { recursive: true });
    mkdirSync(join(root, "work", "public"), { recursive: true });
    writeFileSync(join(root, "work", "clients", "acme.md"), "The audit store is SQLite.\n");
    writeFileSync(join(root, "work", "public", "open.md"), "The audit store is SQLite.\n");
    symlinkSync(join(root, "work"), join(root, "zlink"));
    const folders = [{ root, exclude: ["work/clients"] }];
    const claimOf = (p: string) => ({ text: "The audit store is SQLite.", sources: [p] });
    // Control: the real spelling is refused.
    const direct = checkClaims(db, [claimOf(join(root, "work", "clients", "acme.md"))], { folders })[0]!;
    assert(direct.status === "NOT_FOUND" && direct.problems.some((p) => p.includes(WHY)), `direct: ${JSON.stringify(direct)}`);
    // The bypass: the same file through an in-root link to its folder.
    const viaLink = checkClaims(db, [claimOf(join(root, "zlink", "clients", "acme.md"))], { folders })[0]!;
    assert(viaLink.status === "NOT_FOUND" && viaLink.problems.some((p) => p.includes(WHY)), `via link: ${JSON.stringify(viaLink)}`);
    // A note not under the exclude, reached through the link, stays judged.
    const open = checkClaims(db, [claimOf(join(root, "zlink", "public", "open.md"))], { folders })[0]!;
    assert(open.status === "SUPPORTED", `a non-excluded note via the link: ${JSON.stringify(open)}`);
    // An in-root link to a single note is still readable.
    symlinkSync(join(root, "work", "public", "open.md"), join(root, "a.md"));
    const leaf = checkClaims(db, [claimOf(join(root, "a.md"))], { folders })[0]!;
    assert(leaf.status === "SUPPORTED", `an in-root link to a note: ${JSON.stringify(leaf)}`);
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

test("oauth", "chamber_check over MCP: instructions in initialize, a check through the real server", async () => {
  const MCP_PATH = join(dirname(fileURLToPath(import.meta.url)), "../src/mcp_server.ts");
  const { env, dir } = stubAskFixture();
  try {
    const init = spawnSync(process.execPath, ["--experimental-strip-types", MCP_PATH], {
      encoding: "utf8",
      env,
      input: `${JSON.stringify({ jsonrpc: "2.0", id: 1, method: "initialize", params: { protocolVersion: "2025-03-26", capabilities: {}, clientInfo: { name: "t", version: "0" } } })}\n`,
      timeout: 30_000,
    });
    const reply = JSON.parse((init.stdout || "").split("\n").find((l) => l.includes('"id":1')) ?? "{}") as { result?: { instructions?: string } };
    assert(/chamber_check/.test(reply.result?.instructions ?? ""), `initialize must carry instructions naming chamber_check: ${init.stdout}`);
    const s = mcpSession(env);
    try {
      const note = join(realpathSync(dir), "docs", "ops.md");
      const ok = await s.tool("chamber_check", { claims: [{ text: "The audit store is SQLite.", sources: [note] }, { text: "The audit store is Postgres.", sources: [note] }] });
      assert(ok.includes("[SUPPORTED] The audit store is SQLite.") && ok.includes("[TERMS_ABSENT] The audit store is Postgres."), ok);
      const bad = await s.tool("chamber_check", { claims: [{ text: "x" }] });
      assert(/^(ERROR|Error)/.test(bad) && bad.includes("sources"), `a malformed claim must be refused, not skipped: ${bad}`);
      // 5. Loose input is refused, not read as "don't record".
      for (const [args, word] of [
        [{ claims: [{ text: "The audit store is SQLite.", sources: [note] }], record: "true" }, "record"],
        [{ claims: [{ text: "The audit store is SQLite.", sources: [note] }], recrod: true }, "recrod"],
        [{ claims: [{ text: "The audit store is SQLite.", source: [note], sources: [note] }] }, "source"],
      ] as const) {
        const out = await s.tool("chamber_check", args as Record<string, unknown>);
        assert(/^(ERROR|Error)/.test(out) && out.includes(word), `must refuse ${JSON.stringify(args)}: ${out}`);
      }
    } finally {
      s.stop();
    }
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test("pins", "claim support: the digits after a decimal point are not a second term", () => {
  // "$4.2M" was checked as 4.2M and also as "2M": NAME (digits then a capital) began again right after the
  // decimal point. chamber_check then reported "does not contain: 4.2M, 2M" against a note saying $2.4M.
  for (const [claim, want] of [
    ["Q3 revenue was $4.2M.", ["4.2M", "Q3"]],
    ["It holds 9.99M rows", ["9.99M"]],
    ["A 1.5GB file", ["1.5", "1.5GB"]],
    ["A 1.2B parameter model", ["1.2", "1.2B"]],
    ["Costs 1,5M EUR", ["1,5M", "EUR"]],
  ] as const) {
    const got = specificTerms(claim, { openings: true }).filter((t) => t !== "3")
    assert(JSON.stringify(got) === JSON.stringify(want), `${claim}: ${JSON.stringify(got)}`);
  }
  assert(JSON.stringify(missingTerms("Q3 revenue was $4.2M [1]", ["Q3 revenue was $2.4M."])) === JSON.stringify(["4.2M"]), "only the real number is reported");
  // The unit stays part of the term: dropping "5GB" must not let a different unit through.
  assert(missingTerms("A 1.5GB file [1]", ["A 1.5TB file"]).includes("1.5GB"), "1.5GB vs 1.5TB is flagged");
  assert(missingTerms("A 1.5GB file [1]", ["A 1.5GB file"]).length === 0, "1.5GB vs 1.5GB passes");
  // A number glued to a letter or `_` cannot match whole, so its tail stays a term, as before: dropping it
  // certified v1.2B against a note saying v1.2C (review of this fix).
  for (const [c, p, t] of [
    ["The v1.2B build [1]", "The v1.2C build", "2B"],
    ["Runs iOS17.4Beta [1]", "Runs iOS17.4Alpha", "4Beta"],
    ["Uses GPT4.5Turbo [1]", "Uses GPT4.5Mini", "5Turbo"],
    ["Ships ver_2.0RC [1]", "Ships ver_2.0GA", "0RC"],
  ] as const) assert(missingTerms(c, [p]).includes(t), `${c} vs ${p} must flag ${t}: ${JSON.stringify(missingTerms(c, [p]))}`);
  // A name right after a full stop between sentences is still a name.
  assert(specificTerms("It shipped in 2024.Tesla bought it", { openings: true }).includes("Tesla"), "a name after a year and a full stop");
});

test("pins", "claim support: a citation's title and path names count; numbers match across scales", () => {
  // Held-out benchmark, 2026-09-28: the model is shown "[n] title (path)" above
  // each passage, and a company named only in its page's path was flagged; and
  // "1 million" / "1M", "11,000" / "11k" were flagged as different numbers.
  const page = (claim: string, body: string, title: string, ref: string): string[] =>
    missingTermsIn(claim, citedPassage(body, title, ref));
  const ref = "2026-09-27__intel/raw/www_ycombinator_com_companies_flexengage.md#p3";
  assert(page("FlexEngage reports $2.4m ARR [1]", "It reports $2.4m ARR.", "Dynamic text", ref).length === 0, "a name from the path counts");
  assert(page("Growth came from Tesla [1]", "Growth came.", "Dynamic text", ref).includes("Tesla"), "a name in neither is still flagged");
  // Digits from a title or path are not evidence: the path's date is not "27".
  assert(page("It grew 27 times [1]", "It grew.", "Report 27", ref).includes("27"), "a number from title/path must not count");
  // A family name before its version number is the name; a compound of
  // common words opening a bold label is ordinary (live vault eval).
  assert(missingTerms("Fine-tuning local LLMs (e.g. Qwen models) on Apple hardware [1]", ["fine-tuning local LLMs (Qwen3.5-122B) on Apple hardware"]).length === 0, "Qwen in Qwen3.5");
  assert(missingTerms("The Moon was bright [1]", ["the Moonlight was bright"]).includes("Moon"), "a letter-letter join is still no edge");
  assert(missingTerms("**Group-level catalogue** includes: Mining (13) [1]", ["Mining (13)"]).length === 0, "Group-level is ordinary");
  // Review H: what title, path and glued suffixes must not supply.
  const cited = (claim: string, body: string, title: string, ref: string): string[] =>
    missingTermsIn(claim, citedPassage(body, title, ref));
  assert(cited("Revenue grew for 5 years [1]", "Revenue grew steadily.", "Five lessons from scaling", "notes/a.md").includes("5"), "a spelled count in the title is not a number");
  assert(cited("The Q team led [1]", "The team led.", "Q3 results", "notes/q3.md").includes("Q"), "Q3 in a title does not supply Q");
  assert(cited("Imports into the UAE were banned [1]", "Imports were banned.", "Reta", "05 - UAE Peptide Lab/reta.md#p0").includes("UAE"), "a folder name vouches for nothing");
  for (const [c, p, t] of [
    ["It has 15 million users [1]", "It has 1,5 million users", "15 million"],
    ["It has 10 million users [1]", "timeout: 10m", "10 million"],
    ["It sold 3 million units [1]", "3M tape", "3 million"],
    ["It has 2k stars [1]", "Founded in 2000", "2k"],
    ["The Series B closed [1]", "a B2B product", "B"],
  ] as const) assert(missingTerms(c, [p]).includes(t), `${c} vs ${p} must flag ${t}: ${JSON.stringify(missingTerms(c, [p]))}`);
  assert(missingTerms("Awards under 1 million AED [1]", ["| **<1M AED** | SaaS"]).length === 0, "a currency after the number makes M a scale");
  for (const [c, p] of [["A 9 metre yacht [1]", "A 9m yacht"], ["A 30 minute timeout [1]", "a 30m timeout"], ["It raised $9M [1]", "raised $9m"], ["It has 11,000 stores [1]", "11k stores"]] as const) {
    assert(missingTerms(c, [p]).length === 0, `${c} vs ${p}: ${JSON.stringify(missingTerms(c, [p]))}`);
  }
  // Scales: by value, both ways; a bare number never matches a scaled one.
  const miss = (c: string, p: string): string[] => missingTerms(c, [p]);
  for (const [c, p] of [
    ["Awards under 1 million AED [1]", "awards < AED 1M"],
    ["Deployed in 11,000 stores [1]", "Deployed in 11k stores"],
    ["It has $2.4 million ARR [1]", "at $2.4m ARR"],
    ["It raised $9M [1]", "raised 9 million dollars"],
  ] as const) assert(miss(c, p).length === 0, `${c} vs ${p}: ${JSON.stringify(miss(c, p))}`);
  for (const [c, p, t] of [
    ["It has 9 users [1]", "9 million users", "9"],
    ["It has 11 stores [1]", "11k stores", "11"],
    ["It fell 5 million [1]", "it fell -5M", "5 million"],
    ["It raised $9M [1]", "raised 90 million", "9M"],
  ] as const) assert(miss(c, p).includes(t), `${c} vs ${p} must flag ${t}: ${JSON.stringify(miss(c, p))}`);
});

test("pins", "claim support: the commit gate reads the citation's title and path", () => {
  const db = freshDb();
  const src = seedPinnedDoc(db, "It reports $2.4m in ARR.", "intel/companies_flexengage.md#p0");
  const r = enforceClaimContract(db, { kind: "assertion", text: "FlexEngage reports $2.4 million in ARR [1]" }, { sources: [src] });
  assert(r.status === "ALLOWED", `a path-named company with a scaled number must commit: ${JSON.stringify(r)}`);
  const bad = enforceClaimContract(db, { kind: "assertion", text: "The company Tesla reports $2.4 million in ARR [1]" }, { sources: [src] });
  assert(bad.status !== "ALLOWED" && (bad.rejectedSources ?? []).some((x) => x.reason.includes("Tesla")), `an unnamed company must not: ${JSON.stringify(bad)}`);
});

test("pins", "debt payment does not write the same pin twice", () => {
  // Round-6 review: the duplicate-pin skip had no test.
  const db = freshDb();
  upsertDocument(db, { id: "note_aed", sourceKind: "vault_page", sourceRef: "aed.md", title: "Currency", body: "User base currency is AED (UAE dirham).", model: "local-hash-v1" });
  const bel = commitBelief(db, { type: "belief", text: "User base currency is AED", sources: [], authorFamily: "test", path: "deep" });
  assert(bel.ok, JSON.stringify(bel));
  const debt = (db.prepare(`SELECT id FROM citation_debt WHERE belief_id = ? AND status = 'pending'`).get(bel.beliefId!) as { id: string }).id;
  proposeDebtPayment(db, debt, { minScore: 0.05, model: "local-hash-v1" });
  proposeDebtPayment(db, debt, { minScore: 0.05, model: "local-hash-v1" });
  const pins = (db.prepare(`SELECT count(*) n FROM belief_source WHERE belief_id = ? AND ref_id = 'note_aed'`).get(bel.beliefId!) as { n: number }).n;
  assert(pins === 1, `proposing twice must leave one pin, got ${pins}`);
});

test("pins", "debt payment writes nothing for a debt that is no longer pending", () => {
  // Round-5 review: status was read outside the lock and never re-checked — a
  // waived debt auto-paid, and re-proposing a paid debt wrote a duplicate pin.
  const db = freshDb();
  upsertDocument(db, { id: "note_aed", sourceKind: "vault_page", sourceRef: "aed.md", title: "Currency", body: "User base currency is AED (UAE dirham).", model: "local-hash-v1" });
  const bel = commitBelief(db, { type: "belief", text: "User base currency is AED", sources: [], authorFamily: "test", path: "deep" });
  assert(bel.ok, JSON.stringify(bel));
  const debt = (db.prepare(`SELECT id FROM citation_debt WHERE belief_id = ? AND status = 'pending'`).get(bel.beliefId!) as { id: string }).id;
  db.prepare(`UPDATE citation_debt SET status = 'waived' WHERE id = ?`).run(debt);
  const r = proposeDebtPayment(db, debt, { minScore: 0.05, model: "local-hash-v1", autoPay: true });
  const status = (db.prepare(`SELECT status FROM citation_debt WHERE id = ?`).get(debt) as { status: string }).status;
  const pins = (db.prepare(`SELECT count(*) n FROM belief_source WHERE belief_id = ?`).get(bel.beliefId!) as { n: number }).n;
  assert(status === "waived" && pins === 0, `a waived debt must stay waived with no pin: status=${status} pins=${pins} ${r.status}`);
});

test("pins", "prune keeps a row a belief started citing after it was listed", () => {
  const dir = mkdtempSync(join(tmpdir(), "chamber-prune-late-pin-"));
  mkdirSync(join(dir, "drafts"));
  writeFileSync(join(dir, "drafts", "c.md"), "# C\n\n## S\n\nRefunds close after thirty days.\n");
  const db = freshDb();
  ingestDirectory(db, dir, { embedBatch: (texts) => embedLocalBatch(texts, "hash") });
  const listed = findExcludedDocuments(db, [{ root: dir, exclude: ["drafts"] }]).flatMap((g) => g.ids);
  const id = listed[0]!;
  const snapshotHash = verifyPin(db, { kind: "vault_page", refId: id, snapshotHash: "" }).actualHash!;
  const r = commitBelief(db, {
    type: "inference",
    text: "refunds close after thirty days",
    sources: [{ kind: "vault_page", refId: id, snapshotHash }],
    authorFamily: "test",
    path: "fast",
    requireVerifiedSupport: true,
  });
  assert(r.ok, JSON.stringify(r));
  const out = pruneDocuments(db, new Set(listed));
  const still = db.prepare(`SELECT count(*) n FROM vector_document WHERE id = ?`).get(id) as { n: number };
  assert(still.n === 1 && out.pinnedSkipped === 1, `a cited row must survive: ${JSON.stringify(out)}`);
  rmSync(dir, { recursive: true, force: true });
});

test("pins", "claim support: the escapes found in review stay closed", async () => {
  // Each line came back ALLOWED over this passage in review, 2026-09-26.
  const passage =
    "Kingroon PLA sells for about $9 per kg on AliExpress and ships to Dubai. Prices checked Mar 5. Contact Müller at the depot. The part costs 1,5 EUR.";
  const escapes = [
    "Manufacturer: Tesla. [1]",
    "Kingroon PLA (Tesla) [1]",
    "Kingroon PLA — Tesla makes it [1]",
    "Kingroon PLA - Tesla makes it [1]",
    "made by Škoda in Ørsted [1]",
    "made by Möbius [1]",
    "sold on eBay [1]",
    "sold by 9XFabs [1]",
    "ships from Mars [1]",
    "ships to Mars [1]",
    "costs $9 billion per kg [1]",
    "costs 9k per kg [1]",
    "costs ٩٠٠ dollars [1]",
    "the part costs 15 EUR [1]",
  ];
  for (const e of escapes) {
    const m = missingTerms(e, [passage]);
    assert(m.length > 0, `${JSON.stringify(e)} found every term in the passage — it must not`);
  }
  // Faithful lines over the same passage must still pass.
  // The last two were false flags on the vault eval after the first round of
  // these fixes: a trailing comma kept on "5," and the lost acronym plural.
  // (These used "Tier 1", which passed only because the passage's decimal
  // "1,5" was read as containing a 1 — the digit-boundary rule now refuses.)
  for (const ok of ["Kingroon PLA sells for about $9 per kg [1]", "Contact Müller at the depot [1]", "It costs 1,5 EUR [1]", "Checked Mar 5: Kingroon [1]", "Mar 5, sold by Kingroon [1]", "Kingroon ships PLAs [1]"]) {
    const m = missingTerms(ok, [passage]);
    assert(m.length === 0, `${JSON.stringify(ok)} flagged ${JSON.stringify(m)}`);
  }

  // The aporia branch: a cited line using "unknown"/"no evidence" skipped the
  // check and still rendered its pin as a source.
  const db = freshDb();
  upsertDocument(db, { sourceKind: "vault_page", sourceRef: "k.md", title: "K", body: passage, model: "local-hash-v1" });
  const r = await runAsk(db, "Kingroon", {
    model: "local-hash-v1",
    complete: async () =>
      "It is unknown to most that Kingroon is made on the Moon and costs $900 per kg [1]",
  });
  assert(r.claims[0]!.citedRefs.length === 0, `no source may be shown under it: ${JSON.stringify(r.claims[0])}`);
  assert(r.claims[0]!.status !== "ALLOWED", JSON.stringify(r.claims[0]));
});

